python3 -c "
import json
with open('/app/resources/treasury_bulletin_2024_12.json') as f:
    data = json.load(f)

# Let's see the structure
def find_key(obj, key):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if k == key:
                print(f'Found: {k}')
            yield from find_key(v, key)
    elif isinstance(obj, list):
        for item in obj:
            yield from find_key(item, key)

# Print first level keys
print('Top keys:', list(data.keys())[:10])
"
